use std::collections::{HashSet,VecDeque};impl Solution{pub fn ladder_length(b:String,e:String,wl:Vec<String>)->i32{let mut d:HashSet<String>=wl.into_iter().collect();if !d.contains(&e){return 0}let mut q=VecDeque::new();q.push_back((b.clone(),1));d.remove(&b);while let Some((w,s))=q.pop_front(){if w==e{return s}let mut a=w.into_bytes();for i in 0..a.len(){let old=a[i];for c in b'a'..=b'z'{a[i]=c;let x=String::from_utf8(a.clone()).unwrap();if d.remove(&x){q.push_back((x,s+1));}}a[i]=old;}}0}}
